public class TextAnalyzerEngine {
    // Check if a single token is a palindrome
    public static boolean isPalindrome(String word) {
        if (word == null || word.length() < 2) return false;
        int left = 0, right = word.length() - 1;
        while (left < right) {
            if (Character.toLowerCase(word.charAt(left)) != Character.toLowerCase(word.charAt(right))) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }

    // Core analytics report generator
    public static String generateReport(String rawText) {
        if (rawText == null || rawText.isBlank()) {
            return "ERROR: Empty text provided";
        }

        String cleaned = rawText.trim();
        String[] words = cleaned.split("\\s+");

        int totalCharsWithSpaces = cleaned.length();
        int totalCharsNoSpaces = cleaned.replace(" ", "").length();
        int vowels = 0, consonants = 0;
        String longestWord = "";
        StringBuilder palindromes = new StringBuilder();

        for (String w : words) {
            // Strip trailing punctuation for clean token analysis
            String cleanWord = w.replaceAll("[^a-zA-Z0-9]", "");
            if (cleanWord.length() > longestWord.length()) {
                longestWord = cleanWord;
            }
            if (isPalindrome(cleanWord)) {
                if (palindromes.length() > 0) palindromes.append(", ");
                palindromes.append(cleanWord);
            }
        }

        // Count vowels and consonants
        String lower = cleaned.toLowerCase();
        for (int i = 0; i < lower.length(); i++) {
            char ch = lower.charAt(i);
            if (Character.isLetter(ch)) {
                if ("aeiou".indexOf(ch) != -1) vowels++;
                else consonants++;
            }
        }

        // Assemble final report
        StringBuilder report = new StringBuilder(256);
        report.append("=== Text Analytics Report ===\n")
              .append("Words: ").append(words.length).append("\n")
              .append("Chars (with spaces): ").append(totalCharsWithSpaces).append("\n")
              .append("Chars (no spaces): ").append(totalCharsNoSpaces).append("\n")
              .append("Vowels: ").append(vowels).append(" | Consonants: ").append(consonants).append("\n")
              .append("Longest Word: ").append(longestWord).append("\n")
              .append("Palindromes Found: ").append(palindromes.length() > 0 ? palindromes.toString() : "None");

        return report.toString();
    }

    public static void main(String[] args) {
        String sample = "The radar showed a level flight over the swift river";
        System.out.println(generateReport(sample));
    }
}

